import java.io.*;
import java.util.*;

public class Main {
    static final int MAX_VALUE = 0;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split("\\s+");
        int n = Integer.parseInt(firstLine[0]);
        int k = Integer.parseInt(firstLine[1]);

        String[] secondLine = br.readLine().split("\\s+");
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = Integer.parseInt(secondLine[i]);
        }

        int even = 0, odd = 0;
        List<Integer> candidateDiffs = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            if (i != 0 && even == odd) {
                candidateDiffs.add(Math.abs(arr[i] - arr[i - 1]));
            }
            if (arr[i] % 2 == 0) {
                even++;
            } else {
                odd++;
            }
        }

        candidateDiffs.sort(Integer::compareTo);
        int operations = 0;
        for (int diff : candidateDiffs) {
            if (k >= diff) {
                operations++;
                k -= diff;
            } else {
                break;
            }
        }
        System.out.println(operations);
    }

    static int gcd(int x, int y) {
        return y == 0 ? x : gcd(y, x % y);
    }

    static int lcm(int x, int y) {
        return x / gcd(x, y) * y;
    }

    static int modPow(int base, int exp, int mod) {
        if (base == 0) return 0;
        if (exp == 0) return 1;
        long res;
        if (exp % 2 == 0) {
            res = modPow(base, exp / 2, mod);
            res = (res * res) % mod;
        } else {
            res = base % mod;
            res = (res * modPow(base, exp - 1, mod)) % mod;
        }
        return (int) ((res + mod) % mod);
    }
}
